  ('essencial', 'Essencial', 'Para começar com um cardápio bonito e sempre atualizado.', 3990, 14990, 12, 11990, 1, 'essential', 3, '{"whatsapp_orders":false,"analytics":false,"reports":false,"advanced_layout":false,"qr_styling":false,"priority_support":false}'::jsonb, 0),
