insert into public.menu_templates (slug, name, segment, description, preview_image_url, tier, version, default_theme, sort_order) values
  ('royal-gold', 'Royal Gold', 'Restaurantes de luxo e steakhouses', 'Preto profundo, dourado e fotografias amplas. Uma carta para casas de alta gastronomia.', 'https://images.unsplash.com/photo-1551218808-94e220e084d2?auto=format&fit=crop&w=1200&q=72', 'premium', 1, '{"colors":{"primary":"#C9A55C","secondary":"#8C7340","background":"#0A0A0A","text":"#E8E2D6","heading":"#F3E7C9","button":"#C9A55C","buttonText":"#0A0A0A","border":"#2E2A22","card":"#141311","highlight":"#E3C786","header":"#0A0A0A","footer":"#050505"},"fonts":{"heading":"cinzel","body":"cormorant","headingScale":1,"bodyScale":1.08,"headingWeight":400,"letterSpacing":0.08},"layout":{"productView":"large","imagePosition":"top","radius":2,"spacing":"airy","showImages":true,"showDescriptions":true,"buttonStyle":"outline","headerStyle":"hero"}}'::jsonb, 0),
  ('pure-minimal', 'Pure Minimal', 'Bistrôs e cafeterias premium', 'Branco, areia e muito respiro. O texto conduz e as fotos aparecem só onde importam.', 'https://images.unsplash.com/photo-1482049016688-2d3e1b311543?auto=format&fit=crop&w=1200&q=72', 'essential', 1, '{"colors":{"primary":"#2B2A27","secondary":"#A8987C","background":"#FBFAF7","text":"#3A3833","heading":"#1F1E1B","button":"#2B2A27","buttonText":"#FBFAF7","border":"#E6E1D7","card":"#FFFFFF","highlight":"#B9A27A","header":"#FBFAF7","footer":"#F2EEE6"},"fonts":{"heading":"manrope","body":"manrope","headingScale":1,"bodyScale":1,"headingWeight":300,"letterSpacing":-0.01},"layout":{"productView":"list","imagePosition":"side","radius":6,"spacing":"airy","showImages":true,"showDescriptions":true,"buttonStyle":"solid","headerStyle":"minimal"}}'::jsonb, 1),
  ('urban-black', 'Urban Black', 'Hamburguerias gourmet', 'Tipografia condensada, vermelho intenso e fotos que ocupam o card inteiro. Feito para dar fome.', 'https://images.unsplash.com/photo-1550547660-d9450f859349?auto=format&fit=crop&w=1200&q=72', 'essential', 1, '{"colors":{"primary":"#C8102E","secondary":"#7A0A1C","background":"#0E0E0E","text":"#EDEDED","heading":"#FFFFFF","button":"#C8102E","buttonText":"#FFFFFF","border":"#2A2A2A","card":"#181818","highlight":"#FFC93C","header":"#0E0E0E","footer":"#000000"},"fonts":{"heading":"bebas","body":"inter","headingScale":1.1,"bodyScale":0.95,"headingWeight":400,"letterSpacing":0.02},"layout":{"productView":"grid","imagePosition":"top","radius":14,"spacing":"normal","showImages":true,"showDescriptions":true,"buttonStyle":"solid","headerStyle":"hero"}}'::jsonb, 2),
  ('tokyo-signature', 'Tokyo Signature', 'Restaurantes japoneses', 'Preto, branco e um único ponto vermelho. Grade precisa e navegação silenciosa.', 'https://images.unsplash.com/photo-1579584425555-c3ce17fd4351?auto=format&fit=crop&w=1200&q=72', 'premium', 1, '{"colors":{"primary":"#B3261E","secondary":"#6B6B6B","background":"#F7F6F3","text":"#1A1A1A","heading":"#0D0D0D","button":"#0D0D0D","buttonText":"#F7F6F3","border":"#D9D6D0","card":"#FFFFFF","highlight":"#B3261E","header":"#F7F6F3","footer":"#0D0D0D"},"fonts":{"heading":"jost","body":"jost","headingScale":1,"bodyScale":0.96,"headingWeight":300,"letterSpacing":0.2},"layout":{"productView":"grid","imagePosition":"top","radius":0,"spacing":"normal","showImages":true,"showDescriptions":true,"buttonStyle":"solid","headerStyle":"minimal"}}'::jsonb, 3),
  ('velvet-lounge', 'Velvet Lounge', 'Bares e coquetelarias', 'Verde profundo, dourado e vinho, com moldura art déco. Os drinks ganham retrato próprio.', 'https://images.unsplash.com/photo-1514362545857-3bc16c4c7d1b?auto=format&fit=crop&w=1200&q=72', 'premium', 1, '{"colors":{"primary":"#C6A15B","secondary":"#6E1F2B","background":"#0F2A22","text":"#E7DFCC","heading":"#F1E4C4","button":"#C6A15B","buttonText":"#0F2A22","border":"#2D4A40","card":"#14342A","highlight":"#8E2A3A","header":"#0C231C","footer":"#0A1D17"},"fonts":{"heading":"italiana","body":"bodoni","headingScale":1.05,"bodyScale":0.98,"headingWeight":400,"letterSpacing":0.06},"layout":{"productView":"large","imagePosition":"top","radius":2,"spacing":"normal","showImages":true,"showDescriptions":true,"buttonStyle":"outline","headerStyle":"hero"}}'::jsonb, 4),
  ('coffee-atelier', 'Coffee Atelier', 'Cafeterias e confeitarias', 'Tons de café e creme, fotos redondas e um clima de balcão de bairro.', 'https://images.unsplash.com/photo-1541167760496-1628856ab772?auto=format&fit=crop&w=1200&q=72', 'essential', 1, '{"colors":{"primary":"#6B4226","secondary":"#C89B6D","background":"#F5EDE1","text":"#3B2A1E","heading":"#2C1D12","button":"#6B4226","buttonText":"#FFF8EE","border":"#E2D3BE","card":"#FFF9F0","highlight":"#B5651D","header":"#EADBC6","footer":"#3B2A1E"},"fonts":{"heading":"fraunces","body":"nunito","headingScale":1,"bodyScale":1,"headingWeight":600,"letterSpacing":-0.01},"layout":{"productView":"list","imagePosition":"side","radius":18,"spacing":"normal","showImages":true,"showDescriptions":true,"buttonStyle":"pill","headerStyle":"hero"}}'::jsonb, 5),
  ('italian-heritage', 'Italian Heritage', 'Restaurantes italianos e pizzarias', 'Papel creme, oliva e terracota. Uma carta clássica de trattoria, com sugestões em molduras ovais.', 'https://images.unsplash.com/photo-1621996346565-e3dbc646d9a9?auto=format&fit=crop&w=1200&q=72', 'premium', 1, '{"colors":{"primary":"#B5552F","secondary":"#5D6B3A","background":"#F6EFE0","text":"#3A3226","heading":"#2F3A1C","button":"#5D6B3A","buttonText":"#F6EFE0","border":"#DCCFB4","card":"#FBF6EA","highlight":"#B5552F","header":"#F6EFE0","footer":"#2F3A1C"},"fonts":{"heading":"playfair","body":"baskerville","headingScale":1,"bodyScale":0.94,"headingWeight":400,"letterSpacing":0},"layout":{"productView":"list","imagePosition":"side","radius":4,"spacing":"normal","showImages":true,"showDescriptions":true,"buttonStyle":"solid","headerStyle":"minimal"}}'::jsonb, 6),
  ('prime-steakhouse', 'Prime Steakhouse', 'Churrascarias premium', 'Grafite e cobre, cortes apresentados como fichas técnicas: peso, origem e maturação.', 'https://images.unsplash.com/photo-1600891964092-4316c288032e?auto=format&fit=crop&w=1200&q=72', 'premium', 1, '{"colors":{"primary":"#C47A45","secondary":"#8A5530","background":"#1B1C1E","text":"#D9D6D1","heading":"#F2EEE8","button":"#C47A45","buttonText":"#151515","border":"#34363A","card":"#232427","highlight":"#E09A62","header":"#141517","footer":"#0F1011"},"fonts":{"heading":"oswald","body":"barlow","headingScale":1,"bodyScale":1,"headingWeight":500,"letterSpacing":0.03},"layout":{"productView":"large","imagePosition":"side","radius":6,"spacing":"normal","showImages":true,"showDescriptions":true,"buttonStyle":"solid","headerStyle":"hero"}}'::jsonb, 7),
  ('sweet-boutique', 'Sweet Boutique', 'Confeitarias e docerias premium', 'Rosa suave, champagne e tipografia caligráfica. Vitrine em mosaico para doces que se vendem pela foto.', 'https://images.unsplash.com/photo-1565958011703-44f9829ba187?auto=format&fit=crop&w=1200&q=72', 'premium', 1, '{"colors":{"primary":"#C46A86","secondary":"#D8B98A","background":"#FFF7F8","text":"#5A3E46","heading":"#7A3E55","button":"#C46A86","buttonText":"#FFFFFF","border":"#F1DCE2","card":"#FFFFFF","highlight":"#D8B98A","header":"#FBE9EE","footer":"#F7E3E8"},"fonts":{"heading":"parisienne","body":"quicksand","headingScale":1.15,"bodyScale":0.98,"headingWeight":400,"letterSpacing":0},"layout":{"productView":"grid","imagePosition":"top","radius":22,"spacing":"normal","showImages":true,"showDescriptions":true,"buttonStyle":"pill","headerStyle":"hero"}}'::jsonb, 8),
  ('ocean-signature', 'Ocean Signature', 'Frutos do mar', 'Azul-marinho, areia e ondas desenhadas. Seções alternadas como faixas de praia.', 'https://images.unsplash.com/photo-1467003909585-2f8a72700288?auto=format&fit=crop&w=1200&q=72', 'premium', 1, '{"colors":{"primary":"#123A5E","secondary":"#4F86A8","background":"#FFFFFF","text":"#22313F","heading":"#0D2B47","button":"#123A5E","buttonText":"#FFFFFF","border":"#DCE5EC","card":"#FFFFFF","highlight":"#D9A441","header":"#0D2B47","footer":"#0D2B47"},"fonts":{"heading":"dm-serif","body":"dm-sans","headingScale":1,"bodyScale":1,"headingWeight":400,"letterSpacing":0},"layout":{"productView":"list","imagePosition":"side","radius":14,"spacing":"normal","showImages":true,"showDescriptions":true,"buttonStyle":"solid","headerStyle":"hero"}}'::jsonb, 9)
